"""Зіставляє всі питання PR з наявним доказом і явно відокремлює непокриті умови."""
from collections import Counter
import json
from pathlib import Path

OUT = Path(__file__).resolve().parent
plan = json.loads((OUT / 'ПЛАН.json').read_text(encoding='utf-8-sig'))
facts = json.loads((OUT / 'факти_питань.json').read_text(encoding='utf-8'))
rows = {row['сцена']: row for row in json.loads((OUT / 'зведення.json').read_text(encoding='utf-8'))}
refused = {}
for line in (OUT / 'done.txt').read_text(encoding='utf-8').splitlines():
    item = json.loads(line)
    if 'відмова_питання' in item:
        refused[(item['сцена'], item['pr'])] = item['відмова_питання']

specific = {
 ('ж7_мінус_вісім_пішки', 2838): ('не виконано', 'План очікує frost; у ВИМІРИ — weather_band="deep_frost", у картці — «сильний мороз». Нагода й ошатність не обрані.'),
 ('ж3_кафе_13', 3483): ('не виконано', 'Пора day/«вдень» збережена, але нагода everyday/«Звичайний день», ошатність не обрана. Очікувана зустріч і парний щабель не доведені.'),
 ('ж3_кафе_20', 3483): ('не виконано', 'Пора evening/«ввечері» збережена, але нагода date/«Побачення», formality=[5,6]; денна пара має everyday і без щабля. Очікувана зустріч у парі не доведена.'),
 ('ж1_профілі_з_розмови', 3494): ('не доведено', 'Прилад пройшов лише перший хід DO=rozmova. Двох профілів Олена/Марія не підготував; відповідь — «Відкрито профіль «Проба РВ-6»». Повернення, ізоляція й відновлення картки не перевірені. rc=0 цього не доводить.'),
 ('ж7_вечеря_сьомій', 3483): ('підтверджено в записі', 'ВИМІРИ: part_of_day="evening"; картка «ввечері», година_моделі=null.'),
 ('ж7_театр_дата', 3483): ('підтверджено в записі', 'Запит містить «19 жовтня ввечері»; part_of_day="evening", картка «ввечері», година_моделі=null: дата не стала годиною.'),
 ('ж2_новорічна_мороз', 2838): ('частково', 'Поточний запис: weather_band="frost", картка «ввечері, мороз». Порівняльний ДО й збереження наступним ходом цим записом не доведені.'),
 ('ж2_різдвяна_вечеря', 2838): ('частково', 'Поточний запис: weather_band="cold", картка «холодно». Порівняльний ДО й наступний хід не перевірені.'),
 ('ж7_робота_можливо_дощ', 2838): ('частково', 'Поточний запис зберігає occasion=work, movement=walk, precipitation=possible_rain без weather_band у ВИМІРИ; картка «можливий дощ». Порівняння з ДО не виконане.'),
 ('ж7_робота_можливо_дощ', 3165): ('частково', 'У ВИМІРИ немає wind_band чи wind_ms; збережено possible_rain. Окремого порівняльного прогону ДО не виконано.'),
 ('ж2_новорічна_мороз', 3165): ('частково', 'У ВИМІРИ немає wind_band чи wind_ms; frost збережено. Окремого порівняльного прогону ДО не виконано.'),
 ('ж3_прогулянка_кофта', 3181): ('не доведено', 'Режим розмови завершено, але пул і жорстке «ні» над складом не порівнювались: цей режим не збирав образів.'),
 ('ж3_кафе_20', 3347): ('не доведено', 'Є запис розмови; replay_опори.py з формами ДО на цьому записі не виконувався. Числа хибних відмов і чужих прийнятих не встановлено.'),
 ('ж5_свято_др', 3347): ('не доведено', 'Є запис розмови; replay_опори.py з формами ДО на цьому записі не виконувався. Числа хибних відмов і чужих прийнятих не встановлено.'),
 ('ж6_побачення_вечір', 3405): ('частково', 'Оглянуто знімок ekran_palitra_seed3.png: видимі назви українськими словами, blue/violet не видно; одна кольорова плитка має підпис «— без тексту». Повноту назв і незлитість усіх відтінків не доведено.'),
 ('ж1_весілля_вечір', 3483): ('не доведено', 'Вечірній паспорт: wedding_guest, evening, formality=[8,8], open_zones=unknown. Денна пара обірвалась з rc=2; рівність щаблів і дозвіл другої відкритої зони не доведені.'),
 ('ж3_театр_тріада', 3176): ('частково', 'Експорт: пал_схема_обрана=так, у суді обрала.scheme=her. Другий варіант «хай обере стилістка» не запускався; обидві гілки питання не доведені.'),
 ('ж3_театр_тріада', 3051): ('не доведено', 'У збереженій знахідці K-COL-03 з сила_нп=0.62 відсутні блокує, для_стиліста й сила_нп_джерело. Експорт не доводить повноти полів конструктора; висновок про внутрішній об’єкт за цим не робиться.'),
 ('ж4_клуб_приховати', 3285): ('частково', 'rise_below_waist_for_taller_goal відсутній у всьому експорті; знахідки K-FIT-04 у судах цієї сцени не отримано, тому наявність очікуваного «утримано» не доведена.'),
 ('ж4_клуб_приховати', 3354): ('частково', 'Паспорт goal=conceal, мета_зони=[живіт]. Три розгорнуті R-CHEV-08 мають hint/0.25 і загальну причину «мета образу — приховати». Окремий випадок пояса не встановлено.'),
}
for pr in (3008, 3161, 3198, 3230, 3342):
    specific[('ж7_мороз_без_відкритого', pr)] = ('частково', 'У паспорті open_zones=none, мета_зони=null; доказ має 4 живі картки. Решту умов питання (порівняння, цитати, приховані поверхні чи межі подолу) цей факт сам по собі не доводить.')

answers = []
for scene, items in plan['scenes'].items():
    row, fact = rows[scene], facts[scene]
    for index, item in enumerate(items, 1):
        if (scene, item['pr']) in refused:
            status, answer = 'відмова режиму', refused[(scene, item['pr'])]
        elif not row['запис_завершено']:
            status, answer = 'не доведено', 'Запис не завершено або результат.json відсутній; події завершення й потрібного набору карток немає. Див. лог сцени та ЗВЕДЕННЯ.md.'
        elif (scene, item['pr']) in specific:
            status, answer = specific[(scene, item['pr'])]
        else:
            status = 'не доведено'
            answer = 'Запис збережено, але окреме мірило цього питання не підтверджене. Червоні звірки, факти суду й карток збережено; порівняльного покращення та виконання додаткових умов не заявлено.'
        answers.append(dict(сцена=scene, номер_питання=index, **item, стан=status, відповідь=answer, доказ=row['тека']))
for scene, items in plan['cloud'].items():
    for item in items:
        answers.append(dict(сцена=scene, **item, стан='у хмарі', відповідь='Не запускається ноутбуком; диспетчерові для хмарної сесії.'))
(OUT / 'питання.json').write_text(json.dumps(answers, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
text = ['# Питання плану: факти та межі доказу', '', 'rc=0 засвідчує завершення режиму приладу, а не всі додаткові умови питання PR. Оцінки живою людиною немає.', '']
for answer in answers:
    text += [f"## {answer['сцена']} · PR #{answer['pr']}", '', answer['question'], '', f"**{answer['стан']}**. {answer['відповідь']}", '']
    if 'доказ' in answer:
        text += [f"Доказ: `{answer['доказ']}`; `факти_питань.json`.", '']
(OUT / 'ПИТАННЯ.md').write_text('\n'.join(text).rstrip() + '\n', encoding='utf-8')
print(json.dumps(dict(Counter(answer['стан'] for answer in answers)), ensure_ascii=False))
